import { expect, type Page } from '@playwright/test';
export class WorkspacePage {
  constructor(private readonly page: Page) {}

  /** Opens a role/workspace route; the test remains responsible for authorization assertions. */
  async open(role: string): Promise<void> {
    await this.page.goto(`/os/w/${role}`);
  }

  /** Checks shared shell text as a reusable UI assertion for workspace tests. */
  async expectShell(): Promise<void> {
    await expect(this.page.locator('body')).toContainText(/TaskyMed|workspace|queue/i);
  }
}
